blocks.content:
1*, *::before, *::after {
2  box-sizing: border-box;
3}
4
5body, p, h1, h2, h3 {
6  margin: 0;
7}
8
9body {
10  font-family: 'Inter';
11  background-color: white;
12}
13
14.container {
15  max-width: 1024px; /* content width 976px + padding left and right 24px + 24px */
16  margin: 0 auto;
17  padding: 0 24px;
18}
19
20.site-header {
21  padding: 16px 0;
22  border-bottom: 1px solid #F3F4F6;
23}
24
25.site-header .container {
26  display: flex;
27  align-items: center;
28  justify-content: space-between;
29}
30
31nav ul {
32  list-style: none;
33  margin: 0;
34  padding: 0;
35  display: flex;
36  gap: 32px;
37}
38
39.brand {
40  font-size: 20px;
41  font-weight: 700;
42  text-decoration: none;
43  color: #1E293B;
44}
45
46nav a {
47  font-size: 14px;
48  text-decoration: none;
49  font-weight: 500;
50  color: #1E293B;
51}
52
53.download-btn {
54  height: 30px;
55  padding: 0 8px;
56  text-decoration: none;
57  font-size: 12px;
58  font-weight: 700;
59  display: flex;
60  justify-content: center;
61  align-items: center;
62  color: #14B8A5;
63}
64
65.download-btn-outline {
66  border: 1px solid #14B8A5;
67  border-radius: 30px;
68}
69
70.hero {
71  padding: 80px 0;
72}
73
74.hero .container {
75  display: flex;
76  flex-direction: column;
77  gap: 64px;
78}
79
80.hero-content {
81  display: grid;
82  grid-template-columns: 220px auto;
83  gap: 64px;
84  align-items: center;
85}
86
87.hero-image {
88  max-width: 224px;
89  border-radius: 24px;
90  border: 1px solid #FFFFFF;
91  background: #F3F4F6;
92}
93
94.hero-image img {
95  width: 100%;
96  height: auto;
97  border-radius: 24px;
98}
99
100.hero-text {
101  display: flex;
102  flex-direction: column;
103  gap: 24px;
104  max-width: 672px;
105}
106
107.hero-text h1 {
108  color: #0F172A;
109  font-family: "Crimson Pro";
110  font-size: 60px;
111  font-weight: 700;
112  margin-bottom: 8px;
113}
114
115.hero-subtitle {
116  color: #14B8A5;
117  font-family: "Crimson Pro";
118  font-size: 20px;
119  font-weight: 400;
120}
121
122.hero-text p {
123  color: #475569;
124  font-size: 18px;
125  font-style: normal;
126  font-weight: 400;
127  line-height: 30px;
128}
129
130.hero-actions {
131  display: flex;
132  align-items: flex-start;
133  gap: 16px;
134}
135
136.btn {
137  display: flex;
138  padding: 12px 24px;
139  flex-direction: column;
140  justify-content: center;
141  align-items: center;
142  font-size: 16px;
143  font-weight: 700;
144  border-radius: 12px;
145  text-decoration: none;
146}
147
148.btn-dark {
149  background-color: #0F172A;
150  color: #ffffff;
151}
152
153.btn-outline-secondary {
154  border: 1px solid #E2E8F0;
155  color: #1E293B;
156  background-color: #ffffff;
157}
158
159.hero-stats {
160  display: grid;
161  grid-template-columns: repeat(4, 1fr);
162  gap: 16px;
163}
164
165.stat-card {
166  display: flex;
167  flex-direction: column;
168  align-items: flex-start;
169  gap: 5px;
170  padding: 16px;
171  border-radius: 16px;
172  border: 1px solid #F1F5F9;
173  background: #F8FAFC;
174}
175
176.stat-card strong {
177  color: #0F172A;
178  font-family: "Crimson Pro";
179  font-size: 24px;
180  font-weight: 700;
181}
182
183.stat-card p {
184  color: #64748B;
185  font-size: 12px;
186  font-weight: 700;
187}
188
189.journey-wrapper {
190  padding: 64px 0;
191  border-top: 1px solid #F3F4F6;
192  display: flex;
193  flex-direction: column;
194  gap: 40px;
195}
196
197.journey h2 {
198  color: #1E293B;
199  font-family: "Crimson Pro";
200  font-size: 30px;
201  font-weight: 700;
202}
203
204.journey h2 .material-icons {
205  color: #14B8A5;
206  font-family: "Material Icons";
207  font-size: 24px;
208  font-weight: 400;
209}
210
211.journey-list {
212  display: flex;
213  flex-direction: column;
214  gap: 40px;
215}
216
217.journey-item {
218  display: grid;
219  grid-template-columns: 180px 1fr;
220  gap: 16px;
221}
222
223.journey-date {
224  color: #94A3B8;
225  font-size: 14px;
226  font-weight: 700;
227  text-transform: uppercase;
228}
229
230.journey-content {
231  display: flex;
232  flex-direction: column;
233  align-items: flex-start;
234  gap: 12px;
235}
236
237.journey-role h3 {
238  color: #0F172A;
239  font-family: "Crimson Pro";
240  font-size: 20px;
241  font-weight: 700;
242  line-height: 30px;
243}
244
245.journey-role p {
246  color: #64748B;
247  font-family: "Crimson Pro";
248  font-size: 16px;
249  font-style: italic;
250  font-weight: 500;
251}
252
253.role-description {
254  color: #475569;
255  font-size: 16px;
256  font-weight: 400;
257  line-height: 24px;
258}
259
260.journey-tags {
261  display: flex;
262  gap: 8px;
263}
264
265.tag {
266  padding: 4px 8px;
267  border-radius: 4px;
268  background: #F1F5F9;
269  color: #1E293B;
270  font-size: 10px;
271  font-weight: 700;
272  text-transform: uppercase;
273}

